const item = $input.first().json;
const headers = item.headers || {};
const body = item.body || {};
const expectedSecret = 'docker-n8n-secret';

if (headers['x-hugo-secret'] !== expectedSecret) {
  return [{ json: { reply: 'No autorizado.', statusCode: 401 } }];
}

const message = String(body.message || '').toLowerCase();
const tasks = Array.isArray(body.tasks) ? body.tasks : [];
const active = tasks.filter((task) => task.status !== 'Terminada');
const completed = tasks.filter((task) => task.status === 'Terminada');

function daysUntil(date) {
  const today = new Date();
  today.setHours(0, 0, 0, 0);
  const due = new Date(`${date}T00:00:00`);
  return Math.round((due.getTime() - today.getTime()) / 86400000);
}

function progress(task) {
  const checklist = Array.isArray(task.checklist) ? task.checklist : [];
  if (!checklist.length) return task.status === 'Terminada' ? 100 : task.status === 'En progreso' ? 45 : 0;
  const done = checklist.filter((item) => item.done).length;
  return Math.round((done / checklist.length) * 100);
}

function riskScore(task) {
  const days = daysUntil(task.dueDate);
  const dueRisk = days < 0 ? 50 : days <= 1 ? 42 : days <= 3 ? 32 : days <= 7 ? 18 : 6;
  const difficultyRisk = task.difficulty === 'Alta' ? 28 : task.difficulty === 'Media' ? 16 : 8;
  const progressRisk = progress(task) < 25 ? 24 : progress(task) < 60 ? 14 : 4;
  const statusRisk = task.status === 'Pendiente' ? 10 : 0;
  return dueRisk + difficultyRisk + progressRisk + statusRisk;
}

const ranked = active
  .map((task) => ({ task, risk: riskScore(task), days: daysUntil(task.dueDate), progress: progress(task) }))
  .sort((a, b) => b.risk - a.risk);

let reply = '';

if (!tasks.length) {
  reply = 'Soy Hugo. Todavia no hay tareas cargadas; crea una actividad y puedo predecir riesgos por fecha, dificultad y avance.';
} else if (message.includes('predic') || message.includes('riesgo') || message.includes('complic')) {
  const top = ranked[0];
  if (!top) {
    reply = `Prediccion: no veo riesgo academico activo. Tenes ${completed.length} tarea(s) terminada(s) y ninguna pendiente.`;
  } else {
    const level = top.risk >= 80 ? 'alto' : top.risk >= 60 ? 'medio' : 'moderado';
    reply = `Prediccion: el mayor riesgo es "${top.task.title}" con nivel ${level}. Vence en ${top.days} dia(s), dificultad ${top.task.difficulty} y avance ${top.progress}%. Mi recomendacion es resolver una subtarea concreta hoy y revisar si podes adelantar la entrega.`;
  }
} else if (message.includes('primero') || message.includes('prioridad') || message.includes('urgente')) {
  const top = ranked[0];
  reply = top
    ? `Empezaria por "${top.task.title}". Combina vencimiento cercano, dificultad ${top.task.difficulty} y avance ${top.progress}%.`
    : 'No tenes tareas activas para priorizar ahora.';
} else if (message.includes('semana') || message.includes('vence') || message.includes('fecha')) {
  const week = active.filter((task) => daysUntil(task.dueDate) <= 7).slice(0, 4);
  reply = week.length
    ? `Esta semana vigilaria: ${week.map((task) => `"${task.title}" (${task.dueDate})`).join(', ')}.`
    : 'No veo tareas activas que venzan esta semana.';
} else if (message.includes('progreso') || message.includes('voy') || message.includes('avance')) {
  const total = tasks.length;
  const pct = total ? Math.round((completed.length / total) * 100) : 0;
  reply = `Vas con ${completed.length}/${total} tarea(s) terminada(s), equivalente a ${pct}%. Te quedan ${active.length} tarea(s) activa(s).`;
} else {
  const top = ranked[0];
  reply = top
    ? `Analice tu agenda. Lo mas sensible ahora es "${top.task.title}" por fecha, dificultad y avance. Puedo darte prioridad, vencimientos o prediccion de riesgo.`
    : 'Tu agenda activa esta libre. Puedo ayudarte cuando cargues nuevas tareas.';
}

return [{ json: { reply, source: 'n8n-hugo', statusCode: 200 } }];
